    var loader = document.getElementById('currency-loading');
    loader.classList.add('visible');
    fetch('https://cdn.jsdelivr.net/npm/@fawazahmed0/currency-api@latest/v1/currencies/eur.json')
      .then(function(r) { return r.json(); })
      .then(function(data) {
        if (data && data.eur) {
          var r = data.eur;
          if (r.ils) rates.ILS = r.ils;
          if (r.usd) rates.USD = r.usd;
          if (r.gbp) rates.GBP = r.gbp;
        }
        loader.classList.remove('visible');
        recalc();
      })
      .catch(function() {
