  function getInt(id) { return parseInt(document.getElementById(id).textContent, 10) || 0; }
  function setNum(id, val) { document.getElementById(id).value = val; }

  /* ─── Stepper factory ─── */
  function makeStepper(minusId, valId, plusId, min, max) {
    var valEl = document.getElementById(valId);
    document.getElementById(minusId).addEventListener('click', function() {
      var v = parseInt(valEl.textContent, 10);
      if (v > min) { valEl.textContent = v - 1; recalc(); }
    });
    document.getElementById(plusId).addEventListener('click', function() {
      var v = parseInt(valEl.textContent, 10);
      if (v < max) { valEl.textContent = v + 1; recalc(); }
    });
  }

