    var kidsRow      = document.getElementById('kids-row');
    var bfRow        = document.getElementById('breakfast-row');
    var childPriceRow = document.getElementById('child-price-row');

    tollsRow.style.display = carOn ? '' : 'none';
    if (!carOn) document.getElementById('tolls-check').checked = false;

    kidsRow.style.display = children > 0 ? '' : 'none';
    if (children === 0) document.getElementById('kids-check').checked = false;

    childPriceRow.style.display = children > 0 ? '' : 'none';

