  /* ─── Autofill ─── */
  function autofill() {
    var key = document.getElementById('country').value;
    var c   = COUNTRIES[key];
    if (!c) return;

    var sm = SEASONS[activeSeason];
    var flightClass = getRadio('flight-class') || 'economy';
    var baseFlightAdult = c.flight[flightClass];
    setNum('flight-adult-price', Math.round(baseFlightAdult * sm.flights));
    setNum('flight-child-price', Math.round(baseFlightAdult * 0.7 * sm.flights));

    var hotelType = document.getElementById('hotel-type').value;
    setNum('hotel-price', Math.round(c.hotel[hotelType] * sm.hotel));

    var carCat = document.getElementById('car-category').value;
    var baseCarPrice = c.car[carCat] !== undefined ? c.car[carCat] : c.car['compact'];
    var trans = getRadio('car-transmission') || 'manual';
    var carPrice = trans === 'automatic' ? baseCarPrice * 1.35 : baseCarPrice;
    setNum('car-price', Math.round(carPrice * sm.car));

    var foodStyle = getRadio('food-style') || 'self';
    setNum('food-price', c.food[foodStyle]);

    var actLevel = getRadio('activity-level') || 'light';
    setNum('activity-price', Math.round(c.activities[actLevel] * sm.activities));

    setNum('airport-price', c.airport);

    // Tolls default per country
    if (c.tollsPerDay !== undefined) {
      setNum('tolls-price', c.tollsPerDay);
    }

    // Transport
    var transType = getRadio('transport-type') || 'public';
