  /* ─── Main recalc ─── */
  function recalc() {
    var days        = getInt('days-val');
    var adults      = getInt('adults-val');
    var children    = getInt('children-val');
    var totalPeople = adults + children;

    /* Flights */
    var flightAdultEur = getNum('flight-adult-price');
    var flightChildEur = getNum('flight-child-price');
    var flightsEur     = flightAdultEur * adults + flightChildEur * children;

    /* Luggage */
    var luggageEur = 0;
    if (document.getElementById('lowcost-check').checked) {
      luggageEur = getNum('luggage-price') * adults;
    }

    /* ETIAS */
    var etiasEur = 0;
    if (document.getElementById('etias-check').checked) {
      etiasEur = 20 * adults;
    }

    /* Hotel */
    var rooms      = getInt('rooms-val');
    var hotelNight = getNum('hotel-price');
    var hotelEur   = hotelNight * rooms * days;

    /* City tax */
    var cityTaxEur = 0;
    var key        = document.getElementById('country').value;
    var countryData = COUNTRIES[key];
    if (document.getElementById('citytax-check').checked && countryData) {
      cityTaxEur = countryData.cityTax * totalPeople * days;
    }

    /* Car */
    var carOn     = getRadio('car-toggle') === 'yes';
    var carDays   = getInt('car-days-val');
    var carDayBase = getNum('car-price'); // already has season + auto multiplier applied
    var carEur    = carOn ? carDayBase * carDays : 0;

    /* Local transport (only if no car) */
    var transportEur = 0;
    if (!carOn) {
      transportEur = getNum('transport-price') * days;
    }

    /* Food */
    var foodPerPersonDay = getNum('food-price');
    var foodBase         = foodPerPersonDay * totalPeople * days;
    var tipsPct          = parseInt(tipsSlider.value, 10) / 100;
    var tipsEur          = foodBase * tipsPct;
    var foodEur          = foodBase + tipsEur;

    /* Activities */
    var actPerPersonDay = getNum('activity-price');
    var activitiesEur   = actPerPersonDay * totalPeople * days;

    var dcChecked    = document.getElementById('discount-card-check').checked;
    var dcSavingEur  = 0;
    if (dcChecked && countryData && countryData.discountCard) {
      dcSavingEur   = countryData.discountCard.saving * totalPeople;
      activitiesEur = Math.max(0, activitiesEur - dcSavingEur);
    }

    /* Shopping */
    var shoppingEur = getNum('shopping-price') * adults;

    /* Insurance */
    var insPerPersonDay = getNum('insurance-price');
    var insFamily       = document.getElementById('insurance-family').checked;
    var insEur          = insPerPersonDay * totalPeople * days;
    if (insFamily) insEur *= 0.8;

    /* Comms */
    var commsType = getRadio('comms-type') || 'sim';
    var commsEur  = 0;
    if (commsType === 'sim')      commsEur = 15;
    else if (commsType === 'esim')    commsEur = 20 * totalPeople;
    else if (commsType === 'roaming') commsEur = 8 * totalPeople * days;

    /* Airport (optional) */
    var airportIncluded = document.getElementById('airport-include-check').checked;
    var airportEur = airportIncluded ? getNum('airport-price') : 0;

    /* Parking (₪ converted to EUR for internal calc) */
    var parkingDays = getInt('parking-val');
    var parkingIls  = getNum('parking-price') * parkingDays;
    var parkingEur  = parkingIls / rates.ILS; // ILS → EUR

    /* Extras */
    updateExtrasVisibility();
    var clothingEur  = document.getElementById('clothing-check').checked  ? getNum('clothing-price') : 0;
    var tollsEur     = document.getElementById('tolls-check').checked && carOn ? getNum('tolls-price') * carDays : 0;
    var kidsEur      = document.getElementById('kids-check').checked && children > 0 ? getNum('kids-price') * children * days : 0;
    var bfEur        = (function() {
      if (!document.getElementById('breakfast-check').checked) return 0;
      var ht = document.getElementById('hotel-type').value;
      if (['2star','3star','4star','5star'].indexOf(ht) === -1) return 0;
      return getNum('breakfast-price') * totalPeople * days;
    })();
    var extrasTotal  = clothingEur + tollsEur + kidsEur + bfEur;

    /* Subtotal EUR */
    var subtotalEur = flightsEur + luggageEur + etiasEur +
                      hotelEur + cityTaxEur +
                      carEur + transportEur +
                      foodEur +
                      activitiesEur + shoppingEur +
                      insEur + commsEur + airportEur + parkingEur +
                      extrasTotal;

    /* Buffer */
    var bufferPct = parseInt(bufSlider.value, 10) / 100;
    var bufferEur = subtotalEur * bufferPct;

    /* Grand total in EUR */
    var totalEur = subtotalEur + bufferEur;

    /* Per person / day / night */
    var safePeople = totalPeople || 1;
    var safeDays   = days || 1;
    var perPersonEur = totalEur / safePeople;
    var perDayEur    = totalEur / safeDays;
    var perNightEur  = hotelEur / (days || 1);

    /* Line items in EUR */
    var items = [
      { key: 'flights',    label: '✈️ טיסות',       cls: 'seg-flights',    eur: flightsEur },
      { key: 'luggage',    label: '🧳 מזוודות',      cls: 'seg-luggage',    eur: luggageEur },
      { key: 'etias',      label: '🛂 ETIAS',         cls: 'seg-etias',      eur: etiasEur },
      { key: 'hotel',      label: '🏨 לינה',          cls: 'seg-hotel',      eur: hotelEur },
      { key: 'citytax',    label: '🏙️ מס תיירות',    cls: 'seg-citytax',    eur: cityTaxEur },
      { key: 'car',        label: '🚗 רכב',           cls: 'seg-car',        eur: carEur },
      { key: 'transport',  label: '🚌 תחבורה מקומית', cls: 'seg-transport',  eur: transportEur },
      { key: 'food',       label: '🍽️ אוכל + טיפים',  cls: 'seg-food',       eur: foodEur },
      { key: 'activities', label: '🎡 פעילויות',      cls: 'seg-activities', eur: activitiesEur },
      { key: 'shopping',   label: '🛍️ קניות',         cls: 'seg-shopping',   eur: shoppingEur },
      { key: 'insurance',  label: '🛡️ ביטוח',         cls: 'seg-insurance',  eur: insEur },
      { key: 'comms',      label: '📱 תקשורת',        cls: 'seg-comms',      eur: commsEur },
      { key: 'airport',    label: '🚕 נסיעות שד"ת',   cls: 'seg-airport',    eur: airportEur },
      { key: 'parking',    label: '🅿️ חניה נתב"ג',    cls: 'seg-parking',    eur: parkingEur },
      { key: 'clothing',   label: '👕 ביגוד וציוד',    cls: 'seg-clothing',   eur: clothingEur },
      { key: 'tolls',      label: '🛣️ כבישי אגרה',     cls: 'seg-tolls',      eur: tollsEur },
      { key: 'kids',       label: '🎠 בידור ילדים',    cls: 'seg-kids',       eur: kidsEur },
      { key: 'breakfast',  label: '🍳 ארוחת בוקר',     cls: 'seg-breakfast',  eur: bfEur },
      { key: 'buffer',     label: '📦 חיץ (' + bufSlider.value + '%)', cls: 'seg-buffer', eur: bufferEur },
    ];

    /* ── Extras hint ── */
    var extrasEl = document.getElementById('extras-total-note');
    if (extrasTotal > 0) {
      var extParts = [];
      if (clothingEur > 0) extParts.push('ביגוד: ' + fmtEur(clothingEur));
      if (tollsEur > 0)    extParts.push('אגרה: ' + fmtEur(tollsEur));
      if (kidsEur > 0)     extParts.push('ילדים: ' + fmtEur(kidsEur));
      if (bfEur > 0)       extParts.push('בוקר: ' + fmtEur(bfEur));
      extrasEl.textContent = 'סה"כ הוצאות נוספות: ' + fmtEur(extrasTotal) + ' = ' + fmt(extrasTotal) + ' | ' + extParts.join(' | ');
    } else {
      extrasEl.textContent = '';
    }

    /* ── Hints ── */
    document.getElementById('flight-total-note').textContent =
      'סה"כ טיסות: ' + fmtEur(flightsEur) + ' = ' + fmt(flightsEur) +
      (luggageEur > 0 ? ' | מזוודות: ' + fmtEur(luggageEur) : '') +
      (etiasEur > 0   ? ' | ETIAS: $' + etiasEur : '');

    document.getElementById('hotel-total-note').textContent =
      'סה"כ לינה: ' + fmtEur(hotelEur) + ' = ' + fmt(hotelEur) +
      ' (' + rooms + ' חדר×' + days + ' לילות)' +
      (cityTaxEur > 0 ? ' | מס תיירות: ' + fmtEur(cityTaxEur) : '');

    if (carOn) {
      document.getElementById('car-total-note').textContent =
        'סה"כ רכב: ' + fmtEur(carEur) + ' = ' + fmt(carEur);
    }

    if (!carOn) {
      document.getElementById('transport-total-note').textContent =
        'סה"כ תחבורה מקומית: ' + fmtEur(transportEur) + ' = ' + fmt(transportEur) +
        ' (' + days + ' ימים)';
    }

    var foodNote = 'סה"כ אוכל: ' + fmtEur(foodBase) + ' = ' + fmt(foodBase);
    if (tipsPct > 0) foodNote += ' | טיפים: ' + fmtEur(tipsEur);
    document.getElementById('food-total-note').textContent = foodNote;

    var actNote = 'סה"כ פעילויות: ' + fmtEur(activitiesEur) + ' = ' + fmt(activitiesEur);
    if (dcChecked && dcSavingEur > 0) actNote += ' | חיסכון: ' + fmtEur(dcSavingEur);
    document.getElementById('activity-total-note').textContent = actNote;

    document.getElementById('shopping-total-note').textContent =
      'סה"כ קניות: ' + fmtEur(shoppingEur) + ' = ' + fmt(shoppingEur);

    document.getElementById('insurance-total-note').textContent =
      'סה"כ ביטוח: ' + fmtEur(insEur) + ' = ' + fmt(insEur);

    var commsNote;
    if (commsType === 'sim') {
      commsNote = 'SIM מקומי - חבילה אחת למשפחה | עלות: ' + fmtEur(commsEur) + ' = ' + fmt(commsEur);
    } else if (commsType === 'esim') {
      commsNote = 'eSIM - ' + fmtEur(20) + ' לנוסע × ' + totalPeople + ' | סה"כ: ' + fmtEur(commsEur) + ' = ' + fmt(commsEur);
    } else {
      commsNote = 'חבילת תקשורת מהארץ - ' + fmtEur(8) + ' לאדם ליום × ' + totalPeople + ' × ' + days + ' ימים | סה"כ: ' + fmtEur(commsEur) + ' = ' + fmt(commsEur);
    }
    document.getElementById('comms-cost-note').textContent = commsNote;

    document.getElementById('parking-total-note').textContent =
      'סה"כ חניה: ' + fmt(parkingEur);

    /* ── Render breakdowns ── */
    renderBreakdown('breakdown-full',   items, totalEur);
    renderBreakdown('breakdown-sticky', items, totalEur);
    renderBar('stacked-bar-full',   items, totalEur);
    renderBar('stacked-bar-sticky', items, totalEur);
    renderPie(items, totalEur);

    /* ── Grand total display ── */
    var sym = SYMBOLS[activeCurrency];
    var totalDisplay   = fmt(totalEur);
    var eurDisplay     = fmtEur(totalEur);
    var perPersonDisp  = fmt(perPersonEur);
    var perDayDisp     = fmt(perDayEur);
    var perNightDisp   = fmt(perNightEur);

    document.getElementById('grand-total-main').textContent = totalDisplay;
    document.getElementById('grand-total-eur').textContent  = eurDisplay;
    document.getElementById('per-person').textContent       = perPersonDisp;
