    document.getElementById('sticky-total-box').textContent  = totalDisplay;
    document.getElementById('sticky-eur').textContent        = eurDisplay;
    document.getElementById('sticky-per-person').textContent = perPersonDisp;
    document.getElementById('sticky-per-day').textContent    = perDayDisp;

    /* ── Results header ── */
    document.getElementById('results-header-sub').textContent =
      'כל הסכומים ב-' + activeCurrency + ' | 1 EUR = ' +
      rates[activeCurrency].toFixed(activeCurrency === 'ILS' ? 2 : 3) + ' ' + sym;

    /* ── Savings note ── */
    var savingsEl = document.getElementById('savings-note');
    if (dcChecked && dcSavingEur > 0 && countryData && countryData.discountCard) {
      savingsEl.textContent = 'חסכת: ' + fmtEur(dcSavingEur) + ' עם ' + countryData.discountCard.name;
      savingsEl.classList.add('visible');
    } else {
      savingsEl.classList.remove('visible');
    }
  }

  /* ─── Render breakdown list ─── */
  function renderBreakdown(listId, items, totalEur) {
    var ul = document.getElementById(listId);
    ul.innerHTML = '';
    items.forEach(function(item) {
      if (item.eur <= 0) return;
      var li  = document.createElement('li');
      li.className = 'breakdown-item';
      var pct = totalEur > 0 ? Math.round((item.eur / totalEur) * 100) : 0;
      li.innerHTML =
        '<span class="breakdown-item__label">' + item.label +
        ' <span class="breakdown-item__pct">(' + pct + '%)</span></span>' +
        '<span class="breakdown-item__val">' + fmt(item.eur) + '</span>';
      ul.appendChild(li);
    });
  }

  /* ─── Render stacked bar ─── */
  function renderBar(barId, items, totalEur) {
    var bar = document.getElementById(barId);
    bar.innerHTML = '';
    items.forEach(function(item) {
      if (item.eur <= 0) return;
      var pct = totalEur > 0 ? (item.eur / totalEur) * 100 : 0;
      var seg = document.createElement('div');
      seg.className = 'stacked-bar__seg ' + item.cls;
      seg.style.width = pct.toFixed(2) + '%';
      seg.setAttribute('title', item.label + ': ' + Math.round(pct) + '%');
      bar.appendChild(seg);
    });
  }

  /* ─── Render pie chart ─── */
  function renderPie(items, totalEur) {
    var svgG   = document.getElementById('pie-slices');
    var legend = document.getElementById('pie-legend');
    svgG.innerHTML   = '';
    legend.innerHTML = '';

    var R          = 16;
    var C          = 2 * Math.PI * R;
    var offset     = 0;
    var activeItems = items.filter(function(i) { return i.eur > 0; });

    activeItems.forEach(function(item) {
      var pct   = totalEur > 0 ? item.eur / totalEur : 0;
      var dash  = pct * C;
      var color = PIE_COLORS[item.key] || '#ccc';

      var circle = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
      circle.setAttribute('cx', '32');
      circle.setAttribute('cy', '32');
      circle.setAttribute('r', String(R));
      circle.setAttribute('class', 'pie-circle');
      circle.setAttribute('stroke', color);
      circle.setAttribute('stroke-dasharray', dash.toFixed(3) + ' ' + (C - dash).toFixed(3));
      circle.setAttribute('stroke-dashoffset', (-offset).toFixed(3));
      svgG.appendChild(circle);

      offset += dash;

      // Legend item
      var div = document.createElement('div');
      div.className = 'pie-legend-item';
      var pctRnd = Math.round(pct * 100);
      if (pctRnd < 1) return;
      div.innerHTML =
        '<span class="pie-legend-dot" style="background:' + color + '"></span>' +
        '<span>' + item.label + '</span>' +
        '<span class="pie-legend-pct">' + pctRnd + '%</span>';
      legend.appendChild(div);
    });
  }

